package com.hbm.machine.radar;
import com.hbm.item.battery.*;import net.minecraft.core.BlockPos;import net.minecraft.network.RegistryFriendlyByteBuf;import net.minecraft.world.*;import net.minecraft.world.entity.player.*;import net.minecraft.world.inventory.*;import net.minecraft.world.item.ItemStack;
/** Original8linkers+screenlink+battery ten ordinary slots, with exact source role shift routing. */
public final class RadarMenu extends AbstractContainerMenu{public final RadarBlockEntity machine;private final Container inventory;private final BlockPos pos;public RadarMenu(int id,Inventory player,RegistryFriendlyByteBuf b){this(id,player,b.readBlockPos());}private RadarMenu(int id,Inventory player,BlockPos p){this(id,player,player.player.level().getBlockEntity(p) instanceof RadarBlockEntity r?r:new SimpleContainer(10),p);}public RadarMenu(int id,Inventory player,Container inventory,BlockPos p){super(RadarContent.MENU.get(),id);this.inventory=inventory;machine=inventory instanceof RadarBlockEntity r?r:null;pos=p;for(int i=0;i<8;i++)addSlot(new Slot(inventory,i,26+i*18,17));addSlot(new Slot(inventory,8,26,44));addSlot(new Slot(inventory,9,152,44));for(int row=0;row<3;row++)for(int col=0;col<9;col++)addSlot(new Slot(player,9+row*9+col,8+col*18,103+row*18));for(int col=0;col<9;col++)addSlot(new Slot(player,col,8+col*18,161));}public BlockPos position(){return pos;}@Override public boolean stillValid(Player p){return inventory.stillValid(p);}@Override public ItemStack quickMoveStack(Player player,int index){if(index<0||index>=slots.size())return ItemStack.EMPTY;var slot=getSlot(index);if(!slot.hasItem())return ItemStack.EMPTY;var stack=slot.getItem();var copy=stack.copy();if(index<=9){if(!moveItemStackTo(stack,10,slots.size(),true))return ItemStack.EMPTY;}else if(stack.getItem() instanceof HbmBattery||stack.getItem() instanceof CreativeBatteryItem){if(!moveItemStackTo(stack,9,10,false))return ItemStack.EMPTY;}else if(!moveItemStackTo(stack,0,9,false))return ItemStack.EMPTY;if(stack.isEmpty())slot.setByPlayer(ItemStack.EMPTY);else slot.setChanged();return copy;}}
